// Chemistry12thQuiz.jsx
import React, { useState, useEffect, useRef } from "react";

const loadMathJax = () => {
  if (window.MathJax) return Promise.resolve(window.MathJax);

  if (window.__mathJaxPromise) return window.__mathJaxPromise;

  window.__mathJaxPromise = new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-mathjax="true"]');

    if (existing) {
      existing.addEventListener("load", () => resolve(window.MathJax));
      existing.addEventListener("error", reject);
      return;
    }

    window.MathJax = {
      tex: {
        inlineMath: [["$", "$"], ["\\(", "\\)"]],
        displayMath: [["$$", "$$"], ["\\[", "\\]"]]
      },
      option: {
        skipHtmlTags: ["script", "noscript", "style", "textarea", "pre", "code"]
      }
    };

    const script = document.createElement("script");
    script.src = "https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js";
    script.async = true;
    script.dataset.mathjax = "true";
    script.onload = () => resolve(window.MathJax);
    script.onerror = reject;
    document.head.appendChild(script);
  });

  return window.__mathJaxPromise;
};

const RenderedContent = ({ content, style }) => {
  const ref = useRef(null);

  useEffect(() => {
    let cancelled = false;

    const renderMath = async () => {
      try {
        const mathJax = await loadMathJax();
        if (cancelled || !ref.current) return;

        ref.current.innerHTML = content || "";
        await mathJax.typesetPromise([ref.current]);
      } catch (error) {
        if (!cancelled && ref.current) {
          ref.current.innerHTML = content || "";
        }
      }
    };

    renderMath();

    return () => {
      cancelled = true;
    };
  }, [content]);

  return <span ref={ref} style={style} />;
};

